          // 快感冷却
          const pleasureCooldownValue = SafeGetValue(characterData, `${characterKey}.快感冷却`);
          const pleasureCooldownElement = document.getElementById('sy-pleasure-cooldown-value');
          if (pleasureCooldownElement) {
            pleasureCooldownElement.innerText = pleasureCooldownValue == 1 ? '激活' : '未激活';
            pleasureCooldownElement.className = 'value-main ' + (pleasureCooldownValue == 1 ? 'status-danger' : 'status-info');
          }

          // --- NEW: 幸福值 ---
          const happinessValue = SafeGetValue(characterData, `${characterKey}.幸福值`);
          const happinessColor = getHappinessColor(happinessValue);
          updateProgressBar(
            'sy-happiness-bar',
            'sy-happiness-value',
            'sy-happiness-desc',
            happinessValue,
            0,
            100,
            happinessColor
          );

        } else {
          // 清理或设置默认值，如果角色数据不存在
          document.getElementById('status-card').innerHTML = "<p style='color:#888; padding:10px;'>等待角色数据加载...</p>";
        }
      } catch (error) {
        document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        console.error("Status bar Error:", error);
      }
    }

    document.addEventListener('DOMContentLoaded', ()=>{
      setTimeout(()=>{
        return initDisplay();
      }, 100); // Give MVU a moment to provide the latest stat_data
    });
    // Optional: Re-initialize on message updates if the framework supports it
    if (typeof onNewMessage === 'function') {
      const originalOnNewMessage = onNewMessage;
      onNewMessage = function() {
        originalOnNewMessage.apply(this, arguments);
        initDisplay();
      };
    } else {
      // For testing in a browser without the full MVU framework
      // window.onload = initDisplay;
    }
</script>
